using System;
using System.Collections;
using FMODUnity;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class CompanionPanel : MonoBehaviour
{
	public enum State
	{
		NONE,
		SHOP,
		REWARD
	}

	[Header("Companion Spawn Animation")]
	[SerializeField]
	private float companionSpawnOutsideScreenAdjustment;

	[SerializeField]
	private float movementDuration;

	[SerializeField]
	private AnimationCurve movementCurve;

	[Header("Components")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private GameObject companionPrefab;

	[SerializeField]
	private Transform[] companionHolders;

	[Header("Companion Positions")]
	[SerializeField]
	private Transform companionLeftTransform;

	[SerializeField]
	private Transform companionRightTransform;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnChangeCompanion;

	[SerializeField]
	private VoidEvent OnShowShopPanel;

	[SerializeField]
	private VoidEvent OnNewCompanionRewardChosenPositioned;

	[SerializeField]
	private VoidEvent OnHideCompanionPreviewPanel;

	[Header("References")]
	[SerializeField]
	private GameObjectReference companionRewardPanelReference;

	[Header("Achievements")]
	[SerializeField]
	private AchievementData mechanicalBuddyAchievementData;

	[SerializeField]
	private AchievementData loyalPartnerAchievementData;

	[Header("SFX")]
	[SerializeField]
	private EventReference receivingNewSentinelSFX;

	[Header("Map Handler")]
	[SerializeField]
	private MapHandler mapHandler;

	private Vector3[] spawnPositions;

	private RuntimeCompanion runtimeCompanionWaitingToBePlaced;

	private Action<CompanionInitializer> afterPositioningActionCompanionWaitingToBePlaced;

	private Action beforePositioningActionCompanionWaitingToBePlaced;

	private int companionUpgradeAmount = 1;

	private State currentState;

	private bool isChangingSentinels;

	private Action afterBuyingAction;

	public Transform[] CompanionHolders => companionHolders;

	private void Start()
	{
		spawnPositions = new Vector3[2] { companionLeftTransform.position, companionRightTransform.position };
	}

	public void OnInitializeCompanions()
	{
		for (int i = 0; i < currentCompanions.RuntimeCompanions.Count; i++)
		{
			SpawnCompanion(currentCompanions.RuntimeCompanions[i], i, spawnWithPositioningAnimation: false, effectFeedback: false);
		}
	}

	public CompanionInitializer SpawnCompanion(RuntimeCompanion runtimeCompanion, int positioningIndex, bool spawnWithPositioningAnimation, bool effectFeedback)
	{
		mechanicalBuddyAchievementData.Unlock();
		if (runtimeCompanion.CompanionLevel == 4)
		{
			loyalPartnerAchievementData.Unlock();
		}
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(companionPrefab.name, companionHolders[currentCompanions.RuntimeCompanions.IndexOf(runtimeCompanion)]);
		CompanionInitializer componentInChildren = @object.GetComponentInChildren<CompanionInitializer>();
		currentCompanions.ActiveCompanions.Insert(positioningIndex, componentInChildren.gameObject);
		Vector3 vector = spawnPositions[currentCompanions.ActiveCompanions.IndexOf(componentInChildren.gameObject)];
		if (spawnWithPositioningAnimation)
		{
			@object.transform.position = vector + Vector3.left * companionSpawnOutsideScreenAdjustment;
			componentInChildren.InitializeCompanionWithoutEffects(runtimeCompanion, positioningIndex);
		}
		else
		{
			@object.transform.position = vector;
			componentInChildren.InitializeCompanionEntirely(runtimeCompanion, positioningIndex, effectFeedback);
		}
		return componentInChildren;
	}

	public void OnRuntimeCompanionRewardChosen(RuntimeCompanion runtimeCompanion)
	{
		currentState = State.REWARD;
		NewCompanionChosen(runtimeCompanion, delegate(CompanionInitializer companionToPositionInitializer)
		{
			_ = ReferenceSingleton<GameStateManager>.Instance;
			StartCoroutine(AfterPositioningActionCoroutine(companionToPositionInitializer, delegate
			{
				currentState = State.NONE;
				isChangingSentinels = false;
				OnNewCompanionRewardChosenPositioned.Raise();
			}));
		});
	}

	private void NewCompanionChosen(RuntimeCompanion runtimeCompanion, Action<CompanionInitializer> afterPositioningAction, Action beforePositioningAction = null)
	{
		_ = ReferenceSingleton<GameStateManager>.Instance;
		if (currentCompanions.RuntimeCompanions.Count == 0)
		{
			beforePositioningAction?.Invoke();
			isChangingSentinels = false;
			currentCompanions.AddCompanion(runtimeCompanion);
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.NewCompanionAcquired(runtimeCompanion.CompanionData);
			CompanionInitializer companionToPositionInitializer = SpawnCompanion(runtimeCompanion, 0, spawnWithPositioningAnimation: true, effectFeedback: true);
			PositioningAnimation(afterPositioningAction, companionToPositionInitializer);
			currentCompanions.GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference();
		}
		else if (currentCompanions.RuntimeCompanions.Count == 1)
		{
			beforePositioningAction?.Invoke();
			isChangingSentinels = false;
			int num = ((currentCompanions.ActiveCompanions.First().GetComponent<CompanionInitializer>().PositioningIndex == 0) ? 1 : 0);
			currentCompanions.RuntimeCompanions.Insert(num, runtimeCompanion);
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.NewCompanionAcquired(runtimeCompanion.CompanionData);
			CompanionInitializer companionToPositionInitializer2 = SpawnCompanion(runtimeCompanion, num, spawnWithPositioningAnimation: true, effectFeedback: true);
			PositioningAnimation(afterPositioningAction, companionToPositionInitializer2);
			currentCompanions.GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference();
		}
		else
		{
			isChangingSentinels = true;
			OnChangeCompanion.Raise();
			runtimeCompanionWaitingToBePlaced = runtimeCompanion;
			afterPositioningActionCompanionWaitingToBePlaced = afterPositioningAction;
			beforePositioningActionCompanionWaitingToBePlaced = beforePositioningAction;
		}
	}

	public void PositioningAnimation(Action<CompanionInitializer> afterPositioningAction, CompanionInitializer companionToPositionInitializer)
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(receivingNewSentinelSFX);
		Transform skeletonTransform = companionToPositionInitializer.GetComponent<SpriteControl>().SkeletonTransform;
		CompanionCorruptionStats companionCorruptionStats = companionToPositionInitializer.GetComponent<CompanionCorruptionStats>();
		companionCorruptionStats.ToggleAliveCompanion(value: false);
		companionToPositionInitializer.transform.parent.position = spawnPositions[companionToPositionInitializer.PositioningIndex];
		Vector3 startPosition = skeletonTransform.position;
		Vector3 finalPosition = spawnPositions[companionToPositionInitializer.PositioningIndex];
		StartCoroutine(CoroutineUtility.CurveRoutine(movementDuration, movementCurve, delegate(float t, float v)
		{
			skeletonTransform.position = Vector3.Lerp(startPosition, finalPosition, v);
		}, delegate
		{
			companionCorruptionStats.ToggleAliveCompanion(value: true);
			afterPositioningAction?.Invoke(companionToPositionInitializer);
		}));
	}

	public void OnCompanionBought(RuntimeCompanion runtimeCompanion)
	{
		currentState = State.SHOP;
		NewCompanionChosen(runtimeCompanion, delegate(CompanionInitializer companionToPositionInitializer)
		{
			StartCoroutine(AfterPositioningActionCoroutine(companionToPositionInitializer, delegate
			{
				OnShowShopPanel.Raise();
			}));
		}, delegate
		{
			currentState = State.NONE;
			isChangingSentinels = false;
			afterBuyingAction?.Invoke();
			afterBuyingAction = null;
		});
	}

	private IEnumerator AfterPositioningActionCoroutine(CompanionInitializer companionToPositionInitializer, Action afterCompanionEffectsFeedbackAction)
	{
		yield return new WaitForSeconds(0.1f);
		companionToPositionInitializer.InitializeCompanionEffects(effectFeedback: true);
		UnitFeedbackHandler unitFeedbackHandler = companionToPositionInitializer.UnitFeedbackHandler;
		yield return InvokeAlternatives.WaitForFrames(3);
		bool playUpgradeFeedback = unitFeedbackHandler.SpawnFeedbackCoroutine != null;
		yield return new WaitUntil(() => unitFeedbackHandler.SpawnFeedbackCoroutine == null);
		yield return StartCoroutine(companionToPositionInitializer.PowerUpFeedbackCoroutine(playUpgradeFeedback));
		afterCompanionEffectsFeedbackAction();
	}

	public void OnChangeCompanionChosen(GameObject go)
	{
		CompanionInitializer component = go.GetComponent<CompanionInitializer>();
		currentCompanions.RemoveCompanion(component.RuntimeCompanion);
		currentCompanions.ActiveCompanions.Remove(go);
		beforePositioningActionCompanionWaitingToBePlaced?.Invoke();
		beforePositioningActionCompanionWaitingToBePlaced = null;
		RemoveCompanionAnimation(go, delegate
		{
			NewCompanionChosen(runtimeCompanionWaitingToBePlaced, afterPositioningActionCompanionWaitingToBePlaced);
			runtimeCompanionWaitingToBePlaced = null;
			afterPositioningActionCompanionWaitingToBePlaced = null;
			currentCompanions.GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference();
		});
	}

	public void RemoveCompanionAnimation(GameObject go, Action afterRemoveAction)
	{
		Transform skeletonTransform = go.GetComponent<SpriteControl>().SkeletonTransform;
		Vector3 startPosition = skeletonTransform.position;
		Vector3 finalPosition = skeletonTransform.position + Vector3.left * companionSpawnOutsideScreenAdjustment;
		go.GetComponent<UnitsDiceActivation>().StoreDice();
		CompanionCorruptionStats companionCorruptionStats = go.GetComponent<CompanionCorruptionStats>();
		companionCorruptionStats.ToggleAliveCompanion(value: false);
		go.GetComponent<CompanionInitializer>().RemoveAllCompanionEffectsWithCallbacks();
		StartCoroutine(CoroutineUtility.CurveRoutine(movementDuration, movementCurve, delegate(float t, float v)
		{
			skeletonTransform.position = Vector3.Lerp(startPosition, finalPosition, v);
		}, delegate
		{
			companionCorruptionStats.ToggleAliveCompanion(value: true);
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(go.transform.parent.gameObject);
			afterRemoveAction?.Invoke();
		}));
	}

	public void OnGainRandomCompanionUpgradeReward(int companionUpgradeAmount)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		if (IsAnyCompanionAndCompanionNotMaxLevel())
		{
			currentCompanions.ActiveCompanions.PickRandom().GetComponent<CompanionInitializer>().UpgradeCompanionXTimes(companionUpgradeAmount);
		}
		ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
	}

	public void OnGainAllCompanionUpgradeReward(int companionUpgradeAmount)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		if (IsAnyCompanionAndCompanionNotMaxLevel())
		{
			for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
			{
				CompanionInitializer component = currentCompanions.ActiveCompanions[i].GetComponent<CompanionInitializer>();
				if (component.CompanionLevel < 4)
				{
					component.UpgradeCompanionXTimes(companionUpgradeAmount);
				}
			}
		}
		ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
	}

	public void OnCompanionPreviewBackButtonPressed()
	{
		OnHideCompanionPreviewPanel.Raise();
		if (currentState == State.SHOP)
		{
			OnShowShopPanel.Raise();
			afterBuyingAction = null;
		}
		else if (currentState == State.REWARD)
		{
			companionRewardPanelReference.value.GetComponent<CompanionRewardPanel>().BackFromChooseSentinelToBeReplacedPanelPressed();
		}
		currentState = State.NONE;
	}

	public void OnSetBuyingSentinel(Action afterBuyingAction)
	{
		this.afterBuyingAction = afterBuyingAction;
	}

	private bool IsAnyCompanionAndCompanionNotMaxLevel()
	{
		if (currentCompanions.RuntimeCompanions.Count > 0)
		{
			for (int i = 0; i < currentCompanions.RuntimeCompanions.Count; i++)
			{
				if (currentCompanions.RuntimeCompanions[i].CompanionLevel + 1 < 5)
				{
					return true;
				}
			}
		}
		return false;
	}
}
